from typing import Literal

SupportedLanguage = Literal["en", "hi", "ta", "te", "ml"]
SUPPORTED_LANGUAGES = {"en", "hi", "ta", "te", "ml"}


def normalize_language(value: str | None) -> str:
    return value if value in SUPPORTED_LANGUAGES else "en"


DISCLAIMERS: dict[str, str] = {
    "en": "Disclaimer: This summary is generated by AI for informational purposes only and is not a substitute for professional medical advice, diagnosis, or treatment. Always consult your doctor or qualified healthcare provider.",
    "hi": "अस्वीकरण: यह सारांश AI द्वारा केवल जानकारी के लिए बनाया गया है। यह पेशेवर चिकित्सा सलाह, निदान या उपचार का विकल्प नहीं है। हमेशा अपने डॉक्टर या योग्य स्वास्थ्य सेवा प्रदाता से सलाह लें।",
    "ta": "மறுப்பு: இந்தச் சுருக்கம் தகவல் நோக்கத்திற்காக AI மூலம் உருவாக்கப்பட்டது. இது தொழில்முறை மருத்துவ ஆலோசனை, நோயறிதல் அல்லது சிகிச்சைக்கு மாற்றாகாது. எப்போதும் உங்கள் மருத்துவர் அல்லது தகுதியான சுகாதார வழங்குநரை அணுகவும்.",
    "te": "నిరాకరణ: ఈ సారాంశం సమాచార ప్రయోజనాల కోసం AI ద్వారా రూపొందించబడింది. ఇది వృత్తిపరమైన వైద్య సలహా, నిర్ధారణ లేదా చికిత్సకు ప్రత్యామ్నాయం కాదు. ఎల్లప్పుడూ మీ వైద్యుడిని లేదా అర్హత కలిగిన ఆరోగ్య సేవా ప్రదాతను సంప్రదించండి.",
    "ml": "നിരാകരണം: ഈ സംഗ്രഹം വിവര ആവശ്യങ്ങൾക്കായി AI സൃഷ്ടിച്ചതാണ്. ഇത് പ്രൊഫഷണൽ മെഡിക്കൽ ഉപദേശം, രോഗനിർണയം അല്ലെങ്കിൽ ചികിത്സയ്ക്ക് പകരമല്ല. എപ്പോഴും നിങ്ങളുടെ ഡോക്ടറെയോ യോഗ്യതയുള്ള ആരോഗ്യ സേവനദാതാവിനെയോ സമീപിക്കുക.",
}


def disclaimer_for(language: str | None) -> str:
    return DISCLAIMERS[normalize_language(language)]


def add_disclaimer(text: str, language: str | None) -> str:
    disclaimer = disclaimer_for(language)
    cleaned = text.rstrip()
    for known_disclaimer in DISCLAIMERS.values():
        if cleaned.endswith(known_disclaimer):
            cleaned = cleaned[: -len(known_disclaimer)].rstrip()
    return f"{cleaned}\n\n{disclaimer}"
